        lda #<random_table              ; random_ptr = random_table (init_game_variables then clears the high byte)
        sta random_ptr
        lda #>random_table
        sta random_ptr+1
        sei
        jsr init_game_variables
        jsr reset_play_state
        jmp show_title_screen
